    "recs.title_connect_exporter": "Connecter un exporteur de flux",
    "recs.detail_connect_exporter": "Aucun exporteur NetFlow ou IPFIX n\u2019a encore \xE9t\xE9 observ\xE9. Configurez votre passerelle, pare-feu ou commutateur pour exporter les flux vers HomeSec.",
    "recs.title_verify_exporter": "V\xE9rifier la connectivit\xE9 de l\u2019exporteur",
